package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_verifyCheckSum_TriageGen2Test {

    private static final int CHKSUM_OFFSET = 148;
    private static final int CHKSUMLEN = 8;

    /**
     * Helper to create a header buffer of 512 bytes.
     */
    private byte[] createHeader() {
        return new byte[512];
    }

    @Test
    public void testVerifyCheckSum_ValidUnsigned() {
        byte[] header = createHeader();
        // Fill header with some data
        for (int i = 0; i < header.length; i++) {
            header[i] = 1; 
        }
        // Calculate sum: 512 * 1 = 512
        // 512 in octal is 1000. 
        // We need to put '00001000' at CHKSUM_OFFSET
        // But the logic replaces checksum bytes with ' ' (space, ASCII 32) for the sum calculation.
        // Total sum = (Sum of non-checksum bytes) + (Sum of ' ' in checksum area)

        // Let's manually calculate a valid one:
        // Non-checksum area: 512 - 8 = 504 bytes.
        // Let's set all non-checksum bytes to 0.
        // Sum of non-checksum = 0.
        // Checksum area (8 bytes) will be replaced by ' ' (32).
        // Total unsignedSum = 8 * 32 = 256.
        // Total signedSum = 8 * 32 = 256.
        // We need storedSum to be 256. 256 in octal is 400.
        // Octal 400 -> '00000400'

        byte[] header2 = createHeader();
        // Fill non-checksum part with 0
        for (int i = 0; i < CHKSUM_OFFSET; i++) header2[i] = 0;
        for (int i = CHKSUM_OFFSET + CHKSUMLEN; i < 512; i++) header2[i] = 0;

        // Checksum bytes: '0', '0', '0', '0', '0', '4', '0', '0'
        header2[CHKSUM_OFFSET] = '0';
        header2[CHKSUM_OFFSET + 1] = '0';
        header2[CHKSUM_OFFSET + 2] = '0';
        header2[CHKSUM_OFFSET + 3] = '0';
        header2[CHKSUM_OFFSET + 4] = '0';
        header2[CHKSUM_OFFSET + 5] = '4';
        header2[CHKSUM_OFFSET + 6] = '0';
        header2[CHKSUM_OFFSET + 7] = '0';

        // Calculation:
        // storedSum: 0*8+0... + 4 = 4. Wait, the loop: 0*8+0, 0*8+0... 4, 4*8+0=32, 32*8+0=256.
        // unsignedSum: 0 (non-chk) + 8 * 32 (spaces) = 256.
        // Match!
        assertTrue(TarUtils.verifyCheckSum(header2));
    }










}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_verifyCheckSum_TriageGen2Test {

    private static final int CHKSUM_OFFSET = 148;
    private static final int CHKSUMLEN = 8;

    /**
     * Helper to create a header buffer of 512 bytes.
     */
    private byte[] createHeader() {
        return new byte[512];
    }



    @Test
    public void testVerifyCheckSum_ValidSigned() {
        // The logic for signedSum uses the byte value directly.
        // If we use bytes that are negative, signedSum and unsignedSum will differ.
        // However, in the code, the checksum bytes are replaced by ' ' (32), which is positive.
        // The only way signedSum != unsignedSum is if the header contains bytes > 127.

        byte[] header = createHeader();
        // Set one byte to -1 (0xFF)
        header[0] = (byte) 0xFF; 

        // non-checksum sum: 255 (unsigned) or -1 (signed)
        // checksum area sum: 8 * 32 = 256
        // unsignedSum = 255 + 256 = 511
        // signedSum = -1 + 256 = 255

        // We need storedSum to be 511 (unsigned) or 255 (signed).
        // 255 in octal is 377.
        // Let's target signedSum = 255.
        // storedSum for '00000377': 3*8^2 + 7*8 + 7 = 192 + 56 + 7 = 255.

        header[CHKSUM_OFFSET] = '0';
        header[CHKSUM_OFFSET + 1] = '0';
        header[CHKSUM_OFFSET + 2] = '0';
        header[CHKSUM_OFFSET + 3] = '0';
        header[CHKSUM_OFFSET + 4] = '0';
        header[CHKSUM_OFFSET + 5] = '3';
        header[CHKSUM_OFFSET + 6] = '7';
        header[CHKSUM_OFFSET + 7] = '7';

        assertTrue(TarUtils.verifyCheckSum(header));
    }








}

