import static org.junit.Assert.*;

public class TarUtils_verifyCheckSum_TriageGen2Test {

    private static final int CHKSUM_OFFSET = 148;
    private static final int CHKSUMLEN = 8;

    /**
     * Helper to create a header buffer of 512 bytes.
     */
    private byte[] createHeader() {
        return new byte[512];
    }









    @Test
    public void testVerifyCheckSum_NonOctalDigits() {
        // Test the "else if (digits > 0) { digits = 6; }" branch
        // If the first byte is not 0-7, digits remains 0.
        // If the first byte is '8', it goes to else, digits is 0, so nothing happens.
        byte[] header = createHeader();
        header[CHKSUM_OFFSET] = '8'; 
        header[CHKSUM_OFFSET + 1] = '1'; 
        // storedSum = 1
        // unsignedSum = 8 * 32 = 256
        assertFalse(TarUtils.verifyCheckSum(header));
    }


}

